type LoadState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: AppError };

function assertNever(value: never): never { throw new Error(`Unhandled: ${JSON.stringify(value)}`); }
function render(state: LoadState<Customer>) {
  switch (state.status) {
    case 'idle': return '';
    case 'loading': return 'Loading';
    case 'success': return state.data.name;
    case 'error': return state.error.message;
    default: return assertNever(state);
  }
}

function isCustomerDto(value: unknown): value is CustomerDto {
  return typeof value === 'object' && value !== null
